<section class="show-hero"><div class="show-art"><?php if (!empty($settings['artwork'])): ?><img src="/artwork/<?= $escape($settings['artwork']) ?>" alt="<?= $escape($settings['title']) ?> artwork"><?php else: ?><div class="placeholder-art" aria-hidden="true"><span>ON AIR</span><strong>neo.</strong><span>INDEPENDENT VOICES</span></div><?php endif ?></div><div><p class="eyebrow">THE PODCAST · <?= $escape($settings['category']) ?></p><h1><?= $escape($settings['title']) ?></h1><p class="show-description"><?= nl2br($escape($settings['description'])) ?></p><p class="muted">With <?= $escape($settings['owner_name']) ?></p><div class="actions"><a class="button" href="/feeds/audio.xml">Subscribe to audio</a><a class="button secondary" href="/feeds/video.xml">Subscribe to video</a></div></div></section><section><div class="section-heading"><h2>Latest episodes</h2><form method="get" class="search"><label class="sr-only" for="search">Search episodes</label><input id="search" name="q" value="<?= $escape($search) ?>" placeholder="Find an episode…"><button type="submit" class="secondary">Search</button></form></div><?php if (!$episodes): ?><div class="panel empty"><h2><?= $search?'No matching episodes.':'The next great conversation starts soon.' ?></h2><p><?= $search?'Try a different title or topic.':'Subscribe to hear the first episode when it arrives.' ?></p></div><?php endif ?><div class="episode-grid"><?php foreach ($episodes as $e): ?><article class="panel episode-card"><div class="card-top"><span class="badge"><?= $e['video_id']?'VIDEO + AUDIO':'AUDIO' ?></span><time datetime="<?= gmdate('Y-m-d',(int)$e['published_at']) ?>"><?= gmdate('M j, Y',(int)$e['published_at']) ?></time></div><h3><a href="/episodes/<?= $escape($e['id']) ?>"><?= $escape($e['title']) ?></a></h3><p class="excerpt"><?= $escape($e['description']) ?></p><a class="episode-link" href="/episodes/<?= $escape($e['id']) ?>">Tune in <span aria-hidden="true">→</span></a></article><?php endforeach ?></div><nav class="pagination" aria-label="Episode pages"><?php if ($page>1): ?><a href="/?<?= $escape(http_build_query(['q'=>$search,'page'=>$page-1])) ?>">← Previous</a><?php endif ?><?php if ($pages>1): ?><span>Page <?= $page ?> of <?= $pages ?></span><?php endif ?><?php if ($page<$pages): ?><a href="/?<?= $escape(http_build_query(['q'=>$search,'page'=>$page+1])) ?>">Next →</a><?php endif ?></nav></section>
